const stored = <T,>(key: string, fallback: T): T => { try { return JSON.parse(localStorage.getItem(key) || 'null') ?? fallback; } catch { return fallback; } };
function Icon({ name, size = 16 }: { name: string; size?: number }) {
  const paths: Record<string, string> = { save: 'M4 3h12l4 4v14H4z M7 3v7h9V3 M7 21v-7h10v7', play: 'M7 4l13 8-13 8z', grid: 'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z', cube: 'M12 2l9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10', circuit: 'M3 6h5v12H3 M8 9h8 M8 15h8 M16 4v16 M16 6h5 M16 18h5', wave: 'M2 12h4l3-8 6 16 3-8h4', folder: 'M3 6h7l2 3h9v11H3z', plus: 'M12 4v16 M4 12h16', undo: 'M9 5L3 11l6 6 M3 11h11a6 6 0 016 6', redo: 'M15 5l6 6-6 6 M21 11H10a6 6 0 00-6 6', refresh: 'M20 8a8 8 0 10.3 7 M20 3v5h-5', check: 'M4 12l5 5L20 6', tool: 'M14 3a6 6 0 00-7 8l-5 7 4 4 7-5a6 6 0 008-7l-4 4-4-4 4-4z', file: 'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h8', close: 'M5 5l14 14 M5 19L19 5', sun: 'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 11-8 0 4 4 0 018 0', down: 'M6 9l6 6 6-6', warning: 'M12 2l10 19H2z M12 8v6 M12 17v1', export: 'M12 15V2 M7 7l5-5 5 5 M4 13v8h16v-8', stop: 'M5 5h14v14H5z', layers: 'M12 2l10 5-10 5L2 7z M2 12l10 5 10-5 M2 17l10 5 10-5' };
  return <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round"><path d={paths[name] || paths.file}/></svg>;
}
function DeviceInspector({ device, revision, onCommand, readOnly = false }: { device: Device; revision: number; readOnly?: boolean; onCommand: (command: SchematicCommand) => Promise<void> }) {
  const [parameters, setParameters] = useState(device.parameters);
  const [pins, setPins] = useState(device.pins);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [draftRevision, setDraftRevision] = useState(revision);
  const editingId = useRef(device.id);
  useEffect(() => {
    if (editingId.current === device.id && dirty) return;
    editingId.current = device.id; setParameters(device.parameters); setPins(device.pins); setDraftRevision(revision); setDirty(false);
  }, [device, revision, dirty]);
  const resetDraft = () => { setParameters(device.parameters); setPins(device.pins); setDraftRevision(revision); setDirty(false); };
  const apply = async () => {
    setSaving(true);
    try {
      if (JSON.stringify(parameters) !== JSON.stringify(device.parameters)) await onCommand({ type: 'update_device', id: device.id, parameters });
      for (const [pin, net] of Object.entries(pins)) if (device.pins[pin] !== net) await onCommand({ type: 'set_pin', id: device.id, pin, net });
      setDirty(false);
    } catch { /* The transport displays the typed worker error in the shared banner. */ } finally { setSaving(false); }
  };
  return <><div className="inspector-device"><span className={`device-symbol ${device.kind}`}>{device.kind === 'nmos' || device.kind === 'pmos' ? 'M' : device.kind.slice(0, 1).toUpperCase()}</span><div><strong>{device.name}</strong><span>{kindLabels[device.kind]}</span></div><span className="tag">IR</span></div><label className="field-label">Model / subcircuit</label><code className="model-name">{device.model || 'Primitive / native'}</code><div className="inspector-subhead">PARAMETERS <span>실제 netlist에 적용</span></div><div className="parameter-list">{Object.entries(parameters).map(([key, value]) => <label key={key}><span>{key}<small>{key.endsWith('_um') ? 'µm' : ''}</small></span><input disabled={readOnly} aria-label={`${device.name} ${key}`} value={value} onChange={event => { setDirty(true); setParameters(current => ({ ...current, [key]: typeof value === 'number' ? Number(event.target.value) : event.target.value })); }} type={typeof value === 'number' ? 'number' : 'text'} step="any"/></label>)}</div><div className="inspector-subhead">PIN → NET <span>정확한 연결 graph</span></div><div className="parameter-list pin-list">{Object.entries(pins).map(([pin, net]) => <label key={pin}><span className="pin-name">{pin}</span><input disabled={readOnly} aria-label={`${device.name} pin ${pin}`} value={net} placeholder="floating" onChange={event => { setDirty(true); setPins(current => ({ ...current, [pin]: event.target.value })); }}/></label>)}</div><div className="inspector-draft-note" data-testid="inspector-draft">{dirty ? <><span>{draftRevision !== revision ? `입력 유지 · 원본 r${draftRevision}, 현재 r${revision}` : '저장하지 않은 입력'}</span><button className="text-button" onClick={resetDraft}>서버 값으로 되돌리기</button></> : null}</div><button className="button primary full" disabled={saving || readOnly || !dirty} onClick={() => void apply()}><Icon name="check"/>{saving ? '적용 중…' : '변경 적용 / Apply'}</button><p className="inspector-note">W/L 변경은 시뮬레이션에 적용됩니다. 지원하는 PCell만 layout에서 재생성할 수 있습니다.</p><button className="button danger full" disabled={readOnly} onClick={() => void onCommand({ type: 'delete_device', id: device.id }).catch(() => {})}>소자 삭제 / Delete</button></>;
}

export default function App() {
  const calculatorMode = location.pathname === '/' || calculatorPaths.includes(location.pathname);
  const [viewerOnly,setViewerOnly]=useState(()=>new URLSearchParams(location.search).get('mode')==='viewer');
  useEffect(()=>viewerOnly?window.mos?.onMenuCommand?.(command=>{if(command!=='save'&&editingText(document.activeElement))document.execCommand(command);}):undefined,[viewerOnly]);
  if (calculatorMode && !viewerOnly) return <CalculatorHub/>;
  return viewerOnly ? <StandaloneViewer onExit={()=>setViewerOnly(false)}/> : <DesignWorkspace onViewer={()=>setViewerOnly(true)}/>;
}
