  const [viaWidth, setViaWidth] = useState(''), [viaHeight, setViaHeight] = useState('');
  const [artifact, setArtifact] = useState<unknown>(null);
  const [netlister, setNetlister] = useState('native');
  const [analysis, setAnalysis] = useState('tran');
  const [dcSweep, setDcSweep] = useState('vgs'), [vgsBias, setVgsBias] = useState(1.8);
  const [postLayout, setPostLayout] = useState(false);
